import{B as e,Q as t,s as n,z as r}from"./chunks/framework.PLMo9b0p.js";import"./chunks/booker-show-detail-qr-code-share.kghpGyku.js";import"./chunks/booker-rivalry-list.DzGSFQ6n.js";import"./chunks/booker-season-detail.D28b64Zd.js";import"./chunks/booker-tournament-detail-in-progress.RwAml_P0.js";import"./chunks/booker-story-arc-card.tB5p2XjD.js";var i=JSON.parse(`{"title":"Booker","description":"","frontmatter":{},"headers":[],"relativePath":"guide/booker.md","filePath":"guide/booker.md"}`),a={name:`guide/booker.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="booker" tabindex="-1">Booker <a class="header-anchor" href="#booker" aria-label="Permalink to &quot;Booker&quot;">​</a></h1><p>Welcome to the Booker guide. This documentation is automatically generated from the latest game features.</p><h2 id="show-planning-—-stipulation-required-error" tabindex="-1">Show Planning — Stipulation Required Error <a class="header-anchor" href="#show-planning-—-stipulation-required-error" aria-label="Permalink to &quot;Show Planning — Stipulation Required Error&quot;">​</a></h2><p>When a rivalry with heat ≥ 30 is on the card but has no match rule (stipulation), approval is blocked. The error dialog lists each affected rivalry. Edit the segment and add a rule such as Steel Cage or Last Man Standing before approving.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-stipulation-error.png" alt="Show Planning — Stipulation Required Error"></p><hr><h2 id="show-planning-—-proposed-card" tabindex="-1">Show Planning — Proposed Card <a class="header-anchor" href="#show-planning-—-proposed-card" aria-label="Permalink to &quot;Show Planning — Proposed Card&quot;">​</a></h2><p>After the AI proposes segments, the booker reviews the card before approving. Rivalries with heat ≥ 10 that are not on the card will trigger an advisory when the Approve button is clicked.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-proposed-card.png" alt="Show Planning — Proposed Card"></p><hr><h2 id="show-planning-—-unbooked-rivalries-warning" tabindex="-1">Show Planning — Unbooked Rivalries Warning <a class="header-anchor" href="#show-planning-—-unbooked-rivalries-warning" aria-label="Permalink to &quot;Show Planning — Unbooked Rivalries Warning&quot;">​</a></h2><p>When rivalries with heat ≥ 10 are not on the proposed card, a confirmation dialog lists each unbooked feud. The booker can go back and add them, or acknowledge and approve anyway — unbooked rivalries carry over to future shows.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-must-book-warning.png" alt="Show Planning — Unbooked Rivalries Warning"></p><hr><h2 id="qr-code-match-share" tabindex="-1">QR Code Match Share <a class="header-anchor" href="#qr-code-match-share" aria-label="Permalink to &quot;QR Code Match Share&quot;">​</a></h2><p>The QR share button on a match segment opens a dialog with a scannable QR code. The URL uses the machine&#39;s LAN IP address so phones on the same network can navigate directly to the match page.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-detail-qr-code-share.png" alt="QR Code Match Share"></p><hr><h2 id="show-calendar" tabindex="-1">Show Calendar <a class="header-anchor" href="#show-calendar" aria-label="Permalink to &quot;Show Calendar&quot;">​</a></h2><p>The Show Calendar provides a monthly view of every scheduled show in the promotion. Each show appears as a colour-coded event tile on its booked date. Click any tile to jump directly to that show&#39;s detail page. Navigate between months using the prev/next arrows, or click Today to snap back to the current date.</p><p><img src="/atw-rpg/docs/screenshots/show-calendar-overview.png" alt="Show Calendar"></p><hr><h2 id="season-list" tabindex="-1">Season List <a class="header-anchor" href="#season-list" aria-label="Permalink to &quot;Season List&quot;">​</a></h2><p>Browse all seasons with their status, show count, and date range. Click &#39;Details&#39; on any season to open its full detail page, including the awards ceremony results.</p><p><img src="/atw-rpg/docs/screenshots/booker-season-list.png" alt="Season List"></p><hr><h2 id="season-detail" tabindex="-1">Season Detail <a class="header-anchor" href="#season-detail" aria-label="Permalink to &quot;Season Detail&quot;">​</a></h2><p>Full season breakdown showing key stats (status, show count, duration) and the Awards Ceremony section listing Wrestler of the Year, Most Improved, and Most Decorated winners.</p><p><img src="/atw-rpg/docs/screenshots/booker-season-detail.png" alt="Season Detail"></p><hr><h2 id="tournament-bracket-generator" tabindex="-1">Tournament Bracket Generator <a class="header-anchor" href="#tournament-bracket-generator" aria-label="Permalink to &quot;Tournament Bracket Generator&quot;">​</a></h2><p>Plan and run tournaments directly from the Booker dashboard. Choose from Single Elimination or Round Robin formats, auto-seed wrestlers by fan count or pick them manually, and book each round across your scheduled shows.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-list.png" alt="Tournament Bracket Generator"></p><hr><h2 id="tournament-detail-—-scheduled" tabindex="-1">Tournament Detail — Scheduled <a class="header-anchor" href="#tournament-detail-—-scheduled" aria-label="Permalink to &quot;Tournament Detail — Scheduled&quot;">​</a></h2><p>A freshly created tournament shows all entrants seeded and ready. The &#39;Start Tournament&#39; button generates the first-round bracket. Entrants are ranked by seed — 1 vs 8, 2 vs 7, and so on.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-detail-scheduled.png" alt="Tournament Detail — Scheduled"></p><hr><h2 id="tournament-detail-—-in-progress" tabindex="-1">Tournament Detail — In Progress <a class="header-anchor" href="#tournament-detail-—-in-progress" aria-label="Permalink to &quot;Tournament Detail — In Progress&quot;">​</a></h2><p>Live tournament view shows completed round results and the pending next round. The booker can book the upcoming round onto any scheduled show and record match winners as each event is completed.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-detail-in-progress.png" alt="Tournament Detail — In Progress"></p><hr><h2 id="story-arc-wizard" tabindex="-1">Story Arc Wizard <a class="header-anchor" href="#story-arc-wizard" aria-label="Permalink to &quot;Story Arc Wizard&quot;">​</a></h2><p>Three-step wizard for scripting a feud arc: select wrestlers, name the arc and choose its length, then add ordered beats (match type, stipulation, winner control).</p><p><img src="/atw-rpg/docs/screenshots/booker-story-arc-wizard.png" alt="Story Arc Wizard"></p><hr><h2 id="rivalry-detail" tabindex="-1">Rivalry Detail <a class="header-anchor" href="#rivalry-detail" aria-label="Permalink to &quot;Rivalry Detail&quot;">​</a></h2><p>View rivalry details including heat, storyline notes, and dates. Use the Story Arc button to script a multi-beat feud arc for this rivalry.</p><p><img src="/atw-rpg/docs/screenshots/booker-rivalry-detail.png" alt="Rivalry Detail"></p><hr><h2 id="rivalry-list" tabindex="-1">Rivalry List <a class="header-anchor" href="#rivalry-list" aria-label="Permalink to &quot;Rivalry List&quot;">​</a></h2><p>Browse active rivalries between wrestlers — ended feuds are filtered out by default; switch the Status filter to All or Ended to see them. Click any row to open the rivalry detail view where you can manage story arc scripts.</p><p><img src="/atw-rpg/docs/screenshots/booker-rivalry-list.png" alt="Rivalry List"></p><hr><h2 id="add-beat-to-story-arc" tabindex="-1">Add Beat to Story Arc <a class="header-anchor" href="#add-beat-to-story-arc" aria-label="Permalink to &quot;Add Beat to Story Arc&quot;">​</a></h2><p>Append new beats to an existing story arc after it has been saved. The Add Beat dialog offers the same match type, stipulation, winner control and notes fields as the creation wizard, plus external participants — an opponent and run-in extras from outside the feud, with an AI-assisted opponent suggestion.</p><p><img src="/atw-rpg/docs/screenshots/booker-story-arc-add-beat.png" alt="Add Beat to Story Arc"></p><hr><h2 id="story-arc-details" tabindex="-1">Story Arc Details <a class="header-anchor" href="#story-arc-details" aria-label="Permalink to &quot;Story Arc Details&quot;">​</a></h2><p>Step 2 names the arc (pre-filled from the selected wrestlers) and picks its length: Short spans 1 PLE, Medium 2, Long 3. The PLE count is a hard ceiling — once a feud has appeared on that many premium live events, it must culminate.</p><p><img src="/atw-rpg/docs/screenshots/booker-story-arc-details.png" alt="Story Arc Details"></p><hr><h2 id="story-arc-beats" tabindex="-1">Story Arc Beats <a class="header-anchor" href="#story-arc-beats" aria-label="Permalink to &quot;Story Arc Beats&quot;">​</a></h2><p>Step 3 defines the match sequence. Each beat picks a match type and optional stipulation, and decides who controls the outcome: the booker names the planned winner, the AI picks based on story notes, or the system rolls. Mark a beat as the Culmination / Blowoff to close the feud. Roster wrestlers outside the arc can join a beat as an external opponent or run-in extra.</p><p><img src="/atw-rpg/docs/screenshots/booker-story-arc-beats.png" alt="Story Arc Beats"></p><hr><h2 id="edit-story-arc-beat" tabindex="-1">Edit Story Arc Beat <a class="header-anchor" href="#edit-story-arc-beat" aria-label="Permalink to &quot;Edit Story Arc Beat&quot;">​</a></h2><p>Pending beats can be retooled at any time before they play out. The edit dialog loads the beat&#39;s current match type, stipulation, winner control, planned winner, blowoff flag, notes and external participants — saving re-runs the same validation as creation and keeps any show or PLE reservation attached to the beat.</p><p><img src="/atw-rpg/docs/screenshots/booker-story-arc-edit-beat.png" alt="Edit Story Arc Beat"></p><hr><h2 id="story-arc-management" tabindex="-1">Story Arc Management <a class="header-anchor" href="#story-arc-management" aria-label="Permalink to &quot;Story Arc Management&quot;">​</a></h2><p>Every saved arc lives on the rivalry detail as a card with a status badge (Active, Completed, Cancelled). The beat grid lists each beat in order — match type, stipulation, external participants, winner control, blowoff marker and status. Pending beats can be edited or removed and renumber automatically; the arc itself can be renamed, extended with more beats, or cancelled before its culmination.</p><p><img src="/atw-rpg/docs/screenshots/booker-story-arc-card.png" alt="Story Arc Management"></p><hr><h2 id="show-planning-—-tournament-slots-on-the-card" tabindex="-1">Show Planning — Tournament Slots on the Card <a class="header-anchor" href="#show-planning-—-tournament-slots-on-the-card" aria-label="Permalink to &quot;Show Planning — Tournament Slots on the Card&quot;">​</a></h2><p>A one-time tournament attached to this show previews its slots on the proposed card: the payoff (and paced round matches on weekly shows) each appear as a grid row with a Tournament source badge. Seeded brackets preview the real match-ups; unknowable ones show placeholder teams. Delete a row to skip that slot on this show — approving books the slots that remain, exactly once.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-tournament-slots.png" alt="Show Planning — Tournament Slots on the Card"></p><hr><h2 id="faction-rivalry-list" tabindex="-1">Faction Rivalry List <a class="header-anchor" href="#faction-rivalry-list" aria-label="Permalink to &quot;Faction Rivalry List&quot;">​</a></h2><p>Track active feuds between factions — the Status filter defaults to Active and can show All or Ended faction rivalries. Add heat to escalate a faction feud toward a war match.</p><p><img src="/atw-rpg/docs/screenshots/booker-faction-rivalry-list.png" alt="Faction Rivalry List"></p><hr><h2 id="tournament-creation-wizard" tabindex="-1">Tournament Creation Wizard <a class="header-anchor" href="#tournament-creation-wizard" aria-label="Permalink to &quot;Tournament Creation Wizard&quot;">​</a></h2><p>Create a tournament in two steps. Step 1 names the tournament and picks the format (Single Elimination or Round Robin), an optional linked championship, start date, and allowed rules — the seeding step stays locked until these are set. Linking a championship also unlocks the contender-deciding option: the tournament winner becomes the title&#39;s #1 contender instead of challenging. Step 2 chooses how entrants are seeded: automatically by fan count (with a live match-up preview of what Create will build), manual wrestler picking, or deferred so a paired show can seed it on approval.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-creation-wizard.png" alt="Tournament Creation Wizard"></p><hr><h2 id="editing-tournament-seeds" tabindex="-1">Editing Tournament Seeds <a class="header-anchor" href="#editing-tournament-seeds" aria-label="Permalink to &quot;Editing Tournament Seeds&quot;">​</a></h2><p>Before the bracket is generated, seeds stay editable. Move an entrant up or down to change its seed — the round-1 pairing is 1 vs last, 2 vs second-to-last, so reordering directly reshapes the match-ups — or swap in a different wrestler while keeping the seed. When the tournament is linked to a championship, the current titleholder is excluded from seeding and from the swap picker: the champion cannot win the belt from themselves. Seeds lock once the tournament starts.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-seed-editing.png" alt="Editing Tournament Seeds"></p><hr><h2 id="tournament-bracket-generator-—-arrange-match-ups" tabindex="-1">Tournament Bracket Generator — Arrange Match-ups <a class="header-anchor" href="#tournament-bracket-generator-—-arrange-match-ups" aria-label="Permalink to &quot;Tournament Bracket Generator — Arrange Match-ups&quot;">​</a></h2><p>Beyond dragging rows to reorder seeds, the round-1 opponents can be hand-picked: each match pairs its wrestlers at the outer seed positions (1 vs last, 2 vs second-to-last), so Start Tournament generates exactly the arranged match-ups. Odd-sized brackets keep a bye at the middle seed.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-arrange-matchups.png" alt="Tournament Bracket Generator — Arrange Match-ups"></p><hr><h2 id="one-time-tournament-on-a-host-show" tabindex="-1">One-Time Tournament on a Host Show <a class="header-anchor" href="#one-time-tournament-on-a-host-show" aria-label="Permalink to &quot;One-Time Tournament on a Host Show&quot;">​</a></h2><p>For a one-off tournament, attach it directly to a show instead of pairing it with a PLE template (that stays reserved for recurring tournaments). Pick a host show and the payoff books there exactly once — rounds pace automatically onto the weekly shows before it. The payoff match type and rule default to One-on-One but can be anything, e.g. a Free-for-All TLC match for a title.</p><p><img src="/atw-rpg/docs/screenshots/booker-tournament-host-show.png" alt="One-Time Tournament on a Host Show"></p><hr><h2 id="dashboard-with-news-ticker" tabindex="-1">Dashboard with News Ticker <a class="header-anchor" href="#dashboard-with-news-ticker" aria-label="Permalink to &quot;Dashboard with News Ticker&quot;">​</a></h2><p>Latest headlines and rumors are visible directly on the booker dashboard.</p><p><img src="/atw-rpg/docs/screenshots/booker-dashboard-news-ticker.png" alt="Dashboard with News Ticker"></p><hr><h2 id="show-planning" tabindex="-1">Show Planning <a class="header-anchor" href="#show-planning" aria-label="Permalink to &quot;Show Planning&quot;">​</a></h2><p>The Show Planning interface allows you to book matches and segments for an upcoming show. Drag and drop wrestlers to create matches, set stipulations, and define segment types.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning.png" alt="Show Planning"></p><hr><h2 id="match-narration" tabindex="-1">Match Narration <a class="header-anchor" href="#match-narration" aria-label="Permalink to &quot;Match Narration&quot;">​</a></h2><p>Bring your matches to life with AI-generated or manual narration. The Story Director uses match participants, rules, and outcomes to weave a compelling narrative of the action. The new structured transcript format separates objective action from character-driven commentary.</p><p><img src="/atw-rpg/docs/screenshots/booker-match-narration.png" alt="Match Narration"></p><hr><h2 id="show-history" tabindex="-1">Show History <a class="header-anchor" href="#show-history" aria-label="Permalink to &quot;Show History&quot;">​</a></h2><p>View a complete history of all booked shows. Click on any show to view its detailed results, ratings, and match history.</p><p><img src="/atw-rpg/docs/screenshots/booker-show-history.png" alt="Show History"></p><hr>`,114)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};